//! Compare the legacy sparse and opt-in matrix-free rig bundle-adjustment
//! backends on one immutable COLMAP text model.
//!
//! The example is intentionally a single-arm driver.  Run it once with
//! `--solver direct` and once with `--solver matrix-free` under `/usr/bin/time`;
//! each process keeps only one source model and one BA problem in memory.  The
//! source image/point identities are never regenerated by the publisher.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::io::{BufWriter, Read, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use nalgebra::{Point2, Point3, Quaternion, UnitQuaternion, Vector3};
use sha2::{Digest, Sha256};
use visloc_rs::io::colmap::parse_cameras_txt;
use visloc_rs::slam::{
    BaConfig, BaRigObservation, BundleAdjustment, LinearSolver, MatrixFreeBaOptions,
    MatrixFreeBaRestartOptions, MatrixFreeBaRestartResult, MatrixFreeBaResult, RobustKernel,
};
use visloc_rs::{Camera, CameraModel, Pose, SE3};

const USAGE: &str = "usage: compare_rig_bundle_adjustment --model PATH --rig-manifest PATH \\
    --solver direct|matrix-free --out-dir PATH [--pcg-max-iterations N] [--pcg-relative-tolerance X] [--pcg-max-restarts 0|1]\n\
    or: compare_rig_bundle_adjustment --model PATH --rig-manifest PATH \\
    --export-oracle-fixture PATH";
const CENTER_TOLERANCE_M: f64 = 1.0e-4;
const FIXED_POSE_TOLERANCE_M: f64 = 1.0e-12;
const FIXED_POSE_TOLERANCE_DEG: f64 = 1.0e-12;
const ROTATION_TOLERANCE_DEG: f64 = 1.0e-3;
const QUATERNION_NORM_TOLERANCE: f64 = 1.0e-6;
const INTRINSIC_TOLERANCE: f64 = 1.0e-8;
const MIN_TRACK_OBSERVATIONS: usize = 2;
const MIN_BASELINE_M: f64 = 1.0e-9;
const MIN_DEPTH_M: f64 = 1.0e-12;
const MAX_PCG_ITERATIONS: usize = 128;
const PCG_TOLERANCE: f64 = 1.0e-12;
const BA_MAX_ITERATIONS: usize = 20;
const BA_INITIAL_LAMBDA: f64 = 1.0e-4;
const ORACLE_MAX_VARIABLE_POSES: usize = 512;
const ORACLE_MAX_LANDMARKS: usize = 8_192;
const ORACLE_MAX_OBSERVATIONS: usize = 262_144;
const ORACLE_MAX_SCHUR_SCALARS: usize = 3_072;
const ORACLE_MAX_CROSS_PAIR_WORK: usize = 64_000_000;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SolverArm {
    Direct,
    MatrixFree,
}

impl SolverArm {
    fn parse(value: &str) -> Result<Self, String> {
        match value {
            "direct" => Ok(Self::Direct),
            "matrix-free" => Ok(Self::MatrixFree),
            other => Err(format!(
                "--solver expects direct or matrix-free, got {other:?}"
            )),
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Direct => "direct",
            Self::MatrixFree => "matrix-free",
        }
    }
}

