    #[test]
    fn publication_writer_preserves_image_and_track_identity_without_reparse() {
        let (source, manifest) = publication_fixture();
        validate_source_model(&source, &manifest).unwrap();
        let prepared = build_problem(&source, &manifest).unwrap();
        let output =
            std::env::temp_dir().join(format!("visloc-compare-publication-{}", std::process::id()));
        assert!(!output.exists());
        publish_model(&output, &source, &manifest, &prepared).unwrap();
        assert_eq!(
            fs::read_to_string(output.join("cameras.txt")).unwrap(),
            source.cameras_text
        );
        let written_images =
            parse_images(&fs::read_to_string(output.join("images.txt")).unwrap()).unwrap();
        let written_points =
            parse_points(&fs::read_to_string(output.join("points3D.txt")).unwrap()).unwrap();
        assert_eq!(written_images, source.images);
        assert_eq!(written_points[0].point3d_id, source.points[0].point3d_id);
        assert_eq!(
            written_points[0].color_tokens,
            source.points[0].color_tokens
        );
        assert_eq!(
            written_points[0].track_tokens,
            source.points[0].track_tokens
        );
        assert_eq!(
            written_points[0].observations,
            source.points[0].observations
        );
        let output_points_text = fs::read_to_string(output.join("points3D.txt")).unwrap();
        let output_point_row = output_points_text
            .lines()
            .find(|line| !line.starts_with('#'))
            .unwrap()
            .split_whitespace()
            .collect::<Vec<_>>();
        assert_eq!(output_point_row[7], "0");
        fs::remove_dir_all(output).unwrap();
    }

    #[test]
    fn publisher_failure_removes_staging_and_never_publishes_partial_model() {
        let (source, manifest) = publication_fixture();
        let mut prepared = build_problem(&source, &manifest).unwrap();
        prepared.ba.landmarks.insert(7, Point3::new(0.0, 0.0, -2.0));
        let output =
            std::env::temp_dir().join(format!("visloc-compare-failure-{}", std::process::id()));
        assert!(!output.exists());
        assert!(publish_model(&output, &source, &manifest, &prepared).is_err());
        assert!(!output.exists());
        let staging_prefix = format!(".{}.", output.file_name().unwrap().to_string_lossy());
        let leftovers = fs::read_dir(output.parent().unwrap())
            .unwrap()
            .filter_map(Result::ok)
            .any(|entry| {
                entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with(&staging_prefix)
            });
        assert!(!leftovers);
    }

    #[test]
    fn oracle_fixture_export_is_no_clobber_and_stream_roundtrip_safe() {
        let root = std::env::temp_dir().join(format!(
            "visloc-compare-oracle-export-{}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(root.join("model")).unwrap();
        fs::write(root.join("manifest.txt"), "manifest").unwrap();
        let (source, manifest) = publication_fixture();
        validate_source_model(&source, &manifest).unwrap();
        let prepared = build_problem(&source, &manifest).unwrap();
        let hashes = SourceHashes {
            cameras: "a".repeat(64),
            images: "b".repeat(64),
            points: "c".repeat(64),
            manifest: "d".repeat(64),
            combined: "e".repeat(64),
        };
        let fixture = root.join("oracle.txt");
        export_oracle_fixture(
            &fixture,
            &root.join("model"),
            &root.join("manifest.txt"),
            &hashes,
            &prepared.ba,
        )
        .unwrap();
        let text = fs::read_to_string(&fixture).unwrap();
        assert!(text.contains("VISLOC_BA_ORACLE_FIXTURE 1\n"));
        assert!(text.contains(&format!("SOURCE_SHA256 {}\n", hashes.combined)));
        assert!(text.contains("INITIAL_COST "));
        assert!(text.contains("INITIAL_COST_BITS "));
        assert!(text.contains("POSE 0 "));
        assert!(text.contains("RIG_OBSERVATION 0 7"));
        let original = text.clone();
        assert!(export_oracle_fixture(
            &fixture,
            &root.join("model"),
            &root.join("manifest.txt"),
            &hashes,
            &prepared.ba,
        )
        .is_err());
        assert_eq!(fs::read_to_string(&fixture).unwrap(), original);
        let staging_prefix = ".oracle.txt.staging-";
        let leftovers = fs::read_dir(&root)
            .unwrap()
            .filter_map(Result::ok)
            .any(|entry| {
                entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with(staging_prefix)
            });
        assert!(!leftovers);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn output_path_rejects_nonempty_and_symlink_destinations() {
        let root =
            std::env::temp_dir().join(format!("visloc-compare-paths-{}", std::process::id()));
        assert!(!root.exists());
        fs::create_dir_all(root.join("model")).unwrap();
        fs::write(root.join("manifest.txt"), "manifest").unwrap();
        fs::create_dir(root.join("nonempty")).unwrap();
        fs::write(root.join("nonempty/sentinel"), "keep").unwrap();
        assert!(prepare_output_path(
            &root.join("nonempty"),
            &root.join("model"),
            &root.join("manifest.txt")
        )
        .is_err());
        assert!(
            prepare_output_path(&root, &root.join("model"), &root.join("manifest.txt")).is_err()
        );
        assert!(prepare_output_path(
            &root.join("model/child"),
            &root.join("model"),
            &root.join("manifest.txt")
        )
        .is_err());
        assert_eq!(
            fs::read_to_string(root.join("nonempty/sentinel")).unwrap(),
            "keep"
        );
        #[cfg(unix)]
        {
            std::os::unix::fs::symlink(root.join("model"), root.join("link")).unwrap();
            assert!(prepare_output_path(
                &root.join("link"),
                &root.join("model"),
                &root.join("manifest.txt")
            )
            .is_err());
            std::os::unix::fs::symlink(root.join("missing"), root.join("dangling")).unwrap();
            assert!(prepare_output_path(
                &root.join("dangling"),
                &root.join("model"),
                &root.join("manifest.txt")
            )
            .is_err());
        }
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn connected_components_are_deterministic() {
        let frame_ids = vec![0, 1, 2];
        let mut union_find = FrameUnionFind::new(frame_ids.len());
        union_find.union(0, 1);
        assert_eq!(union_find.components(&frame_ids), vec![vec![0, 1], vec![2]]);
    }

    #[test]
    fn camera_manifest_match_rejects_non_pinhole_or_wrong_intrinsics() {
        let sensor = SensorSpec {
            index: 0,
            camera_id: 1,
            width: 10,
            height: 10,
            fx: 2.0,
            fy: 3.0,
            cx: 4.0,
            cy: 5.0,
            sensor_from_rig: SE3::identity(),
        };
        assert!(camera_matches_manifest(
            &Camera::pinhole(1, 10, 10, 2.0, 3.0, 4.0, 5.0),
            &sensor
        ));
        assert!(!camera_matches_manifest(
            &Camera::pinhole_radial(1, 10, 10, 2.0, 3.0, 4.0, 5.0, 0.1, 0.0),
            &sensor
        ));
    }
